import csv
import json
import re
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path


DATA_DIR = Path("/app/dataset")


def _read_csv(name):
    with (DATA_DIR / name).open(newline="", encoding="utf-8-sig") as f:
        return list(csv.DictReader(f))


def _hamming_distance(a, b):
    if len(a) != len(b):
        return max(len(a), len(b))
    return sum(x != y for x, y in zip(a, b))


def _correct_employee_id(employee_id, employee_ids):
    """Repair invalid PESELs only when the roster has a clear close match."""
    if employee_id in employee_ids:
        return employee_id
    ranked = sorted((_hamming_distance(employee_id, candidate), candidate)
                    for candidate in employee_ids)
    if ranked and ranked[0][0] <= 3 and (len(ranked) == 1 or ranked[0][0] < ranked[1][0]):
        return ranked[0][1]
    return None


def _correct_date(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        # The source contains dates one day past the end of April or June.
        # Clamp only this unambiguous month-end error; discard other bad dates.
        match = re.fullmatch(r"(\d{4})-(\d{2})-(\d{2})", value or "")
        if not match:
            return None
        year, month, day = map(int, match.groups())
        if month < 1 or month > 12:
            return None
        if day == 32:
            return None
        next_month = date(year + (month == 12), month % 12 + 1, 1)
        last_day = next_month - timedelta(days=1)
        if day == last_day.day + 1:
            return last_day
        return None


def _parse_task_ids(value, known_task_ids):
    # Some source lists have a missing leading or trailing bracket. Extracting
    # numeric tokens recovers their valid task IDs while unknown IDs are ignored.
    return [token for token in re.findall(r"\d+", value or "")
            if token in known_task_ids]


def _first_weekday(year, month, weekday):
    first = date(year, month, 1)
    return first + timedelta(days=(weekday - first.weekday()) % 7)


def _billing_boundary(day, weekday):
    boundary = _first_weekday(day.year, day.month, weekday)
    if boundary > day:
        if day.month == 1:
            year, month = day.year - 1, 12
        else:
            year, month = day.year, day.month - 1
        boundary = _first_weekday(year, month, weekday)
    return boundary


def answer() -> dict[str, list[int]]:
    employees = _read_csv("employees.csv")
    tasks = _read_csv("tasks.csv")
    timesheet = _read_csv("timesheet.csv")

    employee_by_id = {row["PESEL"]: row for row in employees}
    employee_ids = set(employee_by_id)
    task_pay = {row["task_id"]: Decimal(row["pay_per_completion"])
                for row in tasks}

    cleaned_rows = []
    for row in timesheet:
        employee_id = _correct_employee_id(row.get("employee_id", ""), employee_ids)
        work_date = _correct_date(row.get("date", ""))
        try:
            hours = Decimal(row.get("hours_worked", ""))
        except Exception:
            continue
        if employee_id is None or work_date is None or not hours.is_finite() or hours < 0:
            continue
        cleaned_rows.append((row, employee_id, work_date, hours))

    if not cleaned_rows:
        return {employee_id: [] for employee_id in employee_by_id}

    # Billing periods begin on the weekday of the earliest valid timesheet row.
    earliest = min(item[2] for item in cleaned_rows)
    billing_weekday = earliest.weekday()

    totals = defaultdict(Decimal)
    period_starts = set()
    for row, employee_id, work_date, hours in cleaned_rows:
        period_start = _billing_boundary(work_date, billing_weekday)
        period_starts.add(period_start)
        rate = Decimal(employee_by_id[employee_id]["hourly_rate"])
        bonus = sum((task_pay[task_id] for task_id in
                     _parse_task_ids(row.get("performed_tasks", ""), task_pay)), Decimal(0))
        totals[(employee_id, period_start)] += hours * rate + bonus

    ordered_periods = sorted(period_starts)
    result = {}
    for employee_id in employee_by_id:
        salaries = []
        for period_start in ordered_periods:
            amount = totals[(employee_id, period_start)]
            salaries.append(int(amount.quantize(Decimal("1"), rounding=ROUND_HALF_UP)))
        result[employee_id] = salaries
